dtsPropsFor.Button:
/** Visual style: filled = solid tint bg, tinted = alpha tint bg, plain = no bg */
  variant?: "filled" | "tinted" | "plain";
  /** Orthogonal to variant -- swaps tint to --color-destructive */
  role?: "default" | "destructive";
  /** Controls padding and icon size. sm still reaches a 44px touch target at compact via padding/pseudo-element expansion. */
  size?: "sm" | "md" | "lg";
  /** Icon before the label */
  leadingIcon?: IconName;
  /** Icon after the label */
  trailingIcon?: IconName;
  /** Disables interaction, shows a spinner, keeps layout stable */
  loading?: boolean;
  /** Disables interaction */
  disabled?: boolean;
  /** Stretches the button to fill its container */
  fullWidth?: boolean;
  /** Border-radius style */
  corner?: "standard" | "squircle";
  /** Required (TypeScript-enforced) when there are no children (icon-only button) */
  "aria-label"?: string;
  children?: React.ReactNode;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  className?: string;

dtsPropsFor.Icon:
/** Icon identifier from the icon registry */
  name: IconName;
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /** "currentColor" inherits the surrounding text color; otherwise a semantic color token */
  color?: "currentColor" | string;
  /** Marks the icon as purely decorative, skipped by screen readers. Mutually exclusive with aria-label -- set exactly one. */
  decorative?: boolean;
  /** Required when decorative is not set -- accessible label for a meaningful icon */
  "aria-label"?: string;
  className?: string;

dtsPropsFor.HStack:
justify?: "start" | "center" | "end" | "between" | "around" | "evenly";
  align?: "start" | "center" | "end" | "stretch" | "baseline";
  wrap?: "nowrap" | "wrap" | "wrap-reverse";
  gap?: GapToken;
  /** Marks this element as a container-query root (`container-type: inline-size`). Default true. */
  container?: boolean;
  as?: "div" | "article" | "section" | "header" | "footer" | "nav" | "ul" | "li" | "form";
  children?: React.ReactNode;
  className?: string;
  id?: string;
  style?: React.CSSProperties;

dtsPropsFor.VStack:
justify?: "start" | "center" | "end" | "between" | "around" | "evenly";
  align?: "start" | "center" | "end" | "stretch" | "baseline";
  wrap?: "nowrap" | "wrap" | "wrap-reverse";
  gap?: GapToken;
  /** Marks this element as a container-query root (`container-type: inline-size`). Default true. */
  container?: boolean;
  as?: "div" | "article" | "section" | "header" | "footer" | "nav" | "ul" | "li" | "form";
  children?: React.ReactNode;
  className?: string;
  id?: string;
  style?: React.CSSProperties;

dtsPropsFor.Badge:
/** "counter" (default) shows a numeric count or dot; "status" shows a colored label pill. The two modes take different props (see below). */
  variant?: "counter" | "status";
  /** counter mode only -- numeric count to display. count > 99 shows "99+". */
  count?: number;
  /** counter mode only -- show just a dot, no number. Default: false. */
  dot?: boolean;
  /** counter mode only -- render when count === 0. Default: false (hidden). */
  showZero?: boolean;
  /** status mode only, required for that mode -- label text */
  label?: string;
  /** status mode only */
  color?: "tint" | "destructive" | "success" | "warning";
  /** status mode only -- solid = opaque bg (default), tinted = alpha bg */
  tone?: "solid" | "tinted";
  className?: string;

dtsPropsFor.Progress:
/** "circular" (default) is a ring/spinner; "linear" is a bar. linear requires value (always determinate); circular's value is optional (undefined = indeterminate spinner). */
  variant?: "circular" | "linear";
  /** 0-100. Required for linear; optional for circular (undefined = indeterminate). */
  value?: number;
  /** circular mode only -- size preset. */
  size?: "sm" | "md" | "lg";
  /** circular mode only -- escape hatch: exact pixel diameter, bypasses the size preset. */
  diameter?: number;
  /** circular mode only -- stroke width in px, required when using diameter. */
  strokeWidth?: number;
  color?: "tint" | "destructive" | "success" | "warning";
  /** aria-label for accessibility. Required when no surrounding text describes it. */
  label?: string;
  className?: string;
